func (r *DashboardResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan DashboardModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request DashboardModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, req.State.Raw, &request)...)
	var state DashboardModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	// An unset line's default travels only when it changes the stored value (the line was just
	// removed): resending an unchanged default can act on its own, e.g. unpause a group's members.
	if !plan.DateRangeFrom.Equal(state.DateRangeFrom) {
		request.DateRangeFrom = plan.DateRangeFrom
	}
	if !plan.DateRangeTo.Equal(state.DateRangeTo) {
		request.DateRangeTo = plan.DateRangeTo
	}
	if !plan.RefreshInterval.Equal(state.RefreshInterval) {
		request.RefreshInterval = plan.RefreshInterval
	}
	vars := map[string]string{}
	vars["id"] = plan.Id.ValueString()
	out, err := r.client.Update(ctx, dashboardBinding, vars, r.updateBody(ctx, request, plan, state))
	if err != nil {
		addAPIError(&resp.Diagnostics, "updating dashboard", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	r.mergeResponse(ctx, state, out)
	resp.State.Raw = stateFromPlan(req.Plan.Raw, req.State.Raw, out)
}

func (r *DashboardResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var state DashboardModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	vars := map[string]string{}
	vars["id"] = state.Id.ValueString()
	if err := r.client.Delete(ctx, dashboardBinding, vars); err != nil {
		addAPIError(&resp.Diagnostics, "deleting dashboard", err, req.State.Raw.Type())
	}
}

func (r *DashboardResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}

